void warn(const char *fmt, ...) { /* <=== warn */ 
  va_list ap;
  va_start(ap, fmt);
  debugMsg(MSG_WARN, fmt, ap);
  va_end(ap);
}

static unsigned int stringHashFunc(const char *s) { /* <=== stringHashFunc */ 
  unsigned int h = 0;
  while (*s) {
    h = 31*h + *(unsigned char *)s++;
  }
  return h;
}

static void debugMsg(int level, const char *fmt, va_list ap) { /* <=== debugMsg */ 
  if (level <= verbosity) {
    vfprintf(stderr, fmt, ap);
    fputs("\n", stderr);
  }
}

static const char *urlMemstr(const char *buf, int len, const char *s) { /* <=== urlMemstr */ 
  int sLen        = strlen(s);
  if (!sLen) {
    return buf;
  }
  while (len >= sLen) {
    if (len > sLen) {
      char *first = memchr(buf, *s, len - sLen);
      if (!first) {
        return NULL;
      }
      len        -= first - buf;
      buf         = first;
    }
    if (!memcmp(buf, s, sLen)) {
      return buf;
    }
    buf++;
    len--;
  }
  return NULL;
}

char **getRefFromHashMap(const struct HashMap *hashmap, const char *key) { /* <=== getRefFromHashMap */ 
  if (hashmap->mapSize == 0) {
    return NULL;
  }
  unsigned hash = stringHashFunc(key);
  int idx       = hash % hashmap->mapSize;
  if (!hashmap->entries[idx]) {
    return NULL;
  }
  for (int i = 0; hashmap->entries[idx][i].key; i++) {
    if (!strcmp(hashmap->entries[idx][i].key, key)) {
      return (char **)&hashmap->entries[idx][i].value;
    }
  }
  return NULL;
}

static int urlMemcmp(const char *buf, int len, const char *s) { /* <=== urlMemcmp */ 
  int sLen = strlen(s);
  if (len < sLen) {
    return s[len];
  } else {
    return memcmp(buf, s, sLen);
  }
}

const char *getFromHashMap(const struct HashMap *hashmap, const char *key) { /* <=== getFromHashMap */ 
  char **ref = getRefFromHashMap(hashmap, key);
  return ref ? *ref : NULL;
}

